import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"代码评审实践","description":"把评审聚焦在结构、边界和风险上，给出可操作的反馈，让评审成为知识共享而不是挑错大会。","frontmatter":{"title":"代码评审实践","description":"把评审聚焦在结构、边界和风险上，给出可操作的反馈，让评审成为知识共享而不是挑错大会。"},"headers":[],"relativePath":"engineering/code-review.md","filePath":"engineering/code-review.md","lastUpdated":1786264437000}'),i={name:"engineering/code-review.md"};function l(o,t,r,p,d,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="代码评审实践" tabindex="-1">代码评审实践 <a class="header-anchor" href="#代码评审实践" aria-label="Permalink to &quot;代码评审实践&quot;">​</a></h1><p>代码评审（Code Review）最大的价值不是抓几个 typo 或风格问题——那些 lint 工具能做。它真正的作用是：让设计决策被更多人理解、把隐式知识显式化、在合并前发现结构和风险层面的问题。评得好，团队整体水平一起涨；评得差，变成拖慢交付的形式主义。</p><h2 id="评审看什么" tabindex="-1">评审看什么 <a class="header-anchor" href="#评审看什么" aria-label="Permalink to &quot;评审看什么&quot;">​</a></h2><p>把注意力分配到机器查不出、人最有价值的地方：</p><table tabindex="0"><thead><tr><th>层次</th><th>看什么</th><th>例子</th></tr></thead><tbody><tr><td>结构</td><td>设计是否合理，职责是否清晰</td><td>把业务逻辑塞进工具函数、跨层调用</td></tr><tr><td>边界</td><td>异常、空值、并发是否处理</td><td>只考虑正常路径，忘了失败和重试</td></tr><tr><td>风险</td><td>安全、性能、数据完整性</td><td>信任外部输入、N+1 查询、缺事务</td></tr><tr><td>命名</td><td>是否准确传达意图</td><td>叫 <code>data</code> 的变量、叫 <code>process</code> 的函数</td></tr><tr><td>测试</td><td>是否覆盖关键行为，是否测了不该测的</td><td>没有失败路径测试、过度 mock</td></tr></tbody></table><p>风格、格式、import 顺序这类问题，交给 lint 和格式化工具自动处理，不要在评审里反复提。评审者的时间是稀缺资源，要花在机器替代不了的地方。</p><h2 id="怎么给反馈" tabindex="-1">怎么给反馈 <a class="header-anchor" href="#怎么给反馈" aria-label="Permalink to &quot;怎么给反馈&quot;">​</a></h2><p>反馈的质量决定评审是建设性的还是对抗性的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>差的反馈：</span></span>
<span class="line"><span>&quot;这样写不好。&quot;</span></span>
<span class="line"><span>&quot;为什么不用 X？&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>好的反馈：</span></span>
<span class="line"><span>&quot;这里直接读 request.body 没有校验类型，</span></span>
<span class="line"><span>如果传入数组会让后面的 .trim() 报错。</span></span>
<span class="line"><span>建议在入口处加一层校验。&quot;</span></span></code></pre></div><p>几个原则：</p><ul><li><strong>对事不对人</strong>：说&quot;这段代码在并发时可能丢更新&quot;，而不是&quot;你怎么又写了并发 bug&quot;。</li><li><strong>说清为什么</strong>：不光指出问题，还解释为什么是问题、影响是什么。</li><li><strong>给方向而非命令</strong>：提建议和理由，而不是强令对方照你的写法改。除非是明确的错误，否则留空间让作者决策。</li><li><strong>区分必须改和建议</strong>：用&quot;必须&quot;和&quot;建议&quot;区分阻塞性问题和可选优化，别让作者猜哪些不改过不了。</li><li><strong>肯定好的部分</strong>：评审不是只找错，看到清晰的设计、好的命名、周全的测试，说出来，强化这些。</li></ul><h2 id="作者怎么准备评审" tabindex="-1">作者怎么准备评审 <a class="header-anchor" href="#作者怎么准备评审" aria-label="Permalink to &quot;作者怎么准备评审&quot;">​</a></h2><p>评审效率不只取决于评审者，也取决于提交者准备得怎么样：</p><ul><li><strong>PR 要小</strong>：一个 PR 聚焦一件事。几百行的混合改动没人能认真审，最后只能走个过场。</li><li><strong>写清楚背景</strong>：这个改动解决什么问题、采用了什么方案、为什么这么选。评审者没有你的上下文。</li><li><strong>自己先过一遍</strong>：提交前用自己的代码 diff 视角审一遍，常常能发现遗留的调试代码、注释掉的逻辑。</li><li><strong>标注重点</strong>：在复杂或有疑问的地方留注释，引导评审者关注关键部分。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>好的 PR 描述：</span></span>
<span class="line"><span>修复用户重复提交导致订单重复创建的问题。</span></span>
<span class="line"><span>方案：在创建订单前用 Redis SETNX 加幂等锁，</span></span>
<span class="line"><span>锁 key 用 userId + 请求 traceId，TTL 5 分钟。</span></span>
<span class="line"><span>请重点看 lockKey 的生成和失败时的降级逻辑。</span></span></code></pre></div><h2 id="评审的节奏" tabindex="-1">评审的节奏 <a class="header-anchor" href="#评审的节奏" aria-label="Permalink to &quot;评审的节奏&quot;">​</a></h2><p>评审不该成为交付的瓶颈，但也不能无限期搁置：</p><ul><li><strong>当天响应</strong>：收到评审请求尽量当天处理，阻塞的 PR 拖着会迫使作者合并未经审的代码或闲置等待。</li><li><strong>控制单次评审量</strong>：一次审 200-400 行效果最好，超过这个量注意力下降、问题漏看。</li><li><strong>不要囤积</strong>：留一大堆 PR 周五集中审，质量一定差。分散到日常，每次专注。</li></ul><h2 id="当意见不一致时" tabindex="-1">当意见不一致时 <a class="header-anchor" href="#当意见不一致时" aria-label="Permalink to &quot;当意见不一致时&quot;">​</a></h2><p>技术分歧是正常的，处理不好会变成僵局或人情债：</p><ol><li><strong>先理解对方</strong>：复述对方的方案和理由，确认你理解对了再反驳。很多&quot;分歧&quot;其实是误会。</li><li><strong>用事实和权衡</strong>：说清两种方案各自 tradeoff，而不是&quot;我觉得这样更好&quot;。</li><li><strong>小范围验证</strong>：有争议时，写个 spike 或跑个数据，用证据说话。</li><li><strong>知道何时升级</strong>：僵持不下时，找资深成员或负责人决策，而不是在评论里无限轮辩。</li><li><strong>接受合理的不完美</strong>：不是每个分歧都要争出最优解。在不破坏核心约束的前提下，接受作者的选择，记录决策原因，比强求一致更健康。</li></ol><h2 id="务实的评审清单" tabindex="-1">务实的评审清单 <a class="header-anchor" href="#务实的评审清单" aria-label="Permalink to &quot;务实的评审清单&quot;">​</a></h2><ul><li>是否聚焦结构、边界、风险，而不是纠结风格？</li><li>反馈是否说清了原因、区分了必须改和建议？</li><li>PR 是否足够小、背景是否写清楚？</li><li>评审是否及时响应，没有成为交付瓶颈？</li><li>分歧是基于权衡讨论，还是变成了立场之争？</li></ul><p>代码评审是团队里最高频的知识传递场景。一次好的评审，让作者知道为什么这么改、让评审者理解这块业务、让后来的读者从讨论记录里看到决策脉络。把它当作&quot;一起把事情做对&quot;的协作，而不是&quot;我审你&quot;的关卡，它的价值才能真正发挥出来。</p>`,24)])])}const g=a(i,[["render",l]]);export{h as __pageData,g as default};
